-- Add a reusable 150-sentence situational deck with highlighted vocabulary and audio.
insert into public.template_decks (slug, name, description, level)
values (
  'lam-quen-ket-ban-150-cau',
  'Làm quen và kết bạn - 150 câu',
  '150 câu tiếng Trung tự nhiên để làm quen và kết bạn: chào hỏi, giới thiệu bản thân, hỏi quê quán và nghề nghiệp, chia sẻ sở thích, xin WeChat, rủ đi chơi và hẹn gặp lại. Mỗi câu có pinyin, nghĩa tiếng Việt, từ mới được highlight và audio tạo sẵn.',
  'Luyện câu'
)
on conflict (slug) do update
set name = excluded.name, description = excluded.description, level = excluded.level;

with target_deck as (
  select id from public.template_decks where slug = 'lam-quen-ket-ban-150-cau'
)
insert into public.template_sentence_cards (
  template_deck_id, sentence_cn, sentence_pinyin, sentence_vi,
  vocab_json, sentence_audio_url, position
)
select
  target_deck.id, card.sentence_cn, card.sentence_pinyin,
  card.sentence_vi, card.vocab_json::jsonb,
  card.sentence_audio_url, card.position
from target_deck
cross join (
  values
    ('你好，很高兴认识你。', 'Nǐ hǎo, hěn gāoxìng rènshi nǐ.', 'Chào bạn, rất vui được làm quen với bạn.', '[{"chinese":"高兴","pinyin":"gāoxìng","meaning_vi":"vui mừng"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/lam-quen-ket-ban-150-cau/sentence-0b56c819408d241e5b43af8c.mp3', 1),
    ('请问，我该怎么称呼你？', 'Qǐngwèn, wǒ gāi zěnme chēnghu nǐ?', 'Xin hỏi, tôi nên xưng hô với bạn thế nào?', '[{"chinese":"称呼","pinyin":"chēnghu","meaning_vi":"xưng hô, cách gọi"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/lam-quen-ket-ban-150-cau/sentence-fb207b97df614264dd853779.mp3', 2),
    ('我叫小李，你呢？', 'Wǒ jiào Xiǎo Lǐ, nǐ ne?', 'Tôi tên Tiểu Lý, còn bạn?', '[{"chinese":"叫","pinyin":"jiào","meaning_vi":"gọi, tên là"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/lam-quen-ket-ban-150-cau/sentence-c73d3c6142e562efaedb90b6.mp3', 3),
    ('我是越南人，来自河内。', 'Wǒ shì Yuènán rén, láizì Hénèi.', 'Tôi là người Việt Nam, đến từ Hà Nội.', '[{"chinese":"来自","pinyin":"láizì","meaning_vi":"đến từ"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/lam-quen-ket-ban-150-cau/sentence-abb2663d07d91ad40188b163.mp3', 4),
    ('很荣幸能认识大家。', 'Hěn róngxìng néng rènshi dàjiā.', 'Rất vinh hạnh được làm quen với mọi người.', '[{"chinese":"荣幸","pinyin":"róngxìng","meaning_vi":"vinh hạnh"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/lam-quen-ket-ban-150-cau/sentence-85cc046e8793454a44534229.mp3', 5),
    ('这是我的朋友，他叫小王。', 'Zhè shì wǒ de péngyou, tā jiào Xiǎo Wáng.', 'Đây là bạn tôi, bạn ấy tên Tiểu Vương.', '[{"chinese":"朋友","pinyin":"péngyou","meaning_vi":"bạn bè"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/lam-quen-ket-ban-150-cau/sentence-dac6233bc2246b34efeaf2ed.mp3', 6),
    ('我们第一次见面吗？', 'Wǒmen dì yī cì jiànmiàn ma?', 'Chúng ta lần đầu gặp nhau phải không?', '[{"chinese":"第一次","pinyin":"dì yī cì","meaning_vi":"lần đầu"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/lam-quen-ket-ban-150-cau/sentence-91b03021246a48e334015377.mp3', 7),
    ('请告诉我你的名字。', 'Qǐng gàosù wǒ nǐ de míngzì.', 'Xin bạn cho tôi biết tên của bạn.', '[{"chinese":"告诉","pinyin":"gàosù","meaning_vi":"nói cho biết"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/lam-quen-ket-ban-150-cau/sentence-b06b0d27fe680028646fa604.mp3', 8),
    ('你在这里学习中文吗？', 'Nǐ zài zhèlǐ xuéxí Zhōngwén ma?', 'Bạn đang học tiếng Trung ở đây phải không?', '[{"chinese":"学习","pinyin":"xuéxí","meaning_vi":"học"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/lam-quen-ket-ban-150-cau/sentence-5eae967fc91e8ae85de2007e.mp3', 9),
    ('你喜欢和朋友聊天吗？', 'Nǐ xǐhuan hé péngyou liáotiān ma?', 'Bạn thích trò chuyện với bạn bè không?', '[{"chinese":"聊天","pinyin":"liáotiān","meaning_vi":"trò chuyện"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/lam-quen-ket-ban-150-cau/sentence-69ea3a5fffc29d633d0cea28.mp3', 10),
    ('我平时喜欢听音乐和看书。', 'Wǒ píngshí xǐhuan tīng yīnyuè hé kàn shū.', 'Tôi thường thích nghe nhạc và đọc sách.', '[{"chinese":"平时","pinyin":"píngshí","meaning_vi":"thông thường, thường ngày"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/lam-quen-ket-ban-150-cau/sentence-c22ab30227dba669638cdd06.mp3', 11),
    ('我们可以交换联系方式吗？', 'Wǒmen kěyǐ jiāohuàn liánxì fāngshì ma?', 'Chúng ta có thể trao đổi thông tin liên lạc được không?', '[{"chinese":"交换","pinyin":"jiāohuàn","meaning_vi":"trao đổi"},{"chinese":"联系方式","pinyin":"liánxì fāngshì","meaning_vi":"cách thức liên lạc"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/lam-quen-ket-ban-150-cau/sentence-2c0cd8b40ac82d3be3a74d74.mp3', 12),
    ('我喜欢在课堂上认识新朋友。', 'Wǒ xǐhuan zài kètáng shàng rènshi xīn péngyou.', 'Tôi thích làm quen bạn mới trên lớp học.', '[{"chinese":"课堂","pinyin":"kètáng","meaning_vi":"lớp học"},{"chinese":"新","pinyin":"xīn","meaning_vi":"mới"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/lam-quen-ket-ban-150-cau/sentence-d8f15ebd5ad281f122cd6b06.mp3', 13),
    ('我们以后可以多多联系。', 'Wǒmen yǐhòu kěyǐ duōduō liánxì.', 'Chúng ta về sau có thể liên lạc nhiều hơn.', '[{"chinese":"以后","pinyin":"yǐhòu","meaning_vi":"sau này"},{"chinese":"联系","pinyin":"liánxì","meaning_vi":"liên lạc"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/lam-quen-ket-ban-150-cau/sentence-7bb50abb885ff693e1dcb3f1.mp3', 14),
    ('这是我们班的新同学。', 'Zhè shì wǒmen bān de xīn tóngxué.', 'Đây là bạn học mới của lớp chúng tôi.', '[{"chinese":"班","pinyin":"bān","meaning_vi":"lớp học"},{"chinese":"同学","pinyin":"tóngxué","meaning_vi":"bạn học"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/lam-quen-ket-ban-150-cau/sentence-59c6d8af6c404ee69e0fc111.mp3', 15),
    ('请问，你叫什么名字？', 'Qǐngwèn, nǐ jiào shénme míngzì?', 'Xin hỏi, bạn tên gì?', '[{"chinese":"名字","pinyin":"míngzì","meaning_vi":"tên"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/lam-quen-ket-ban-150-cau/sentence-50f6a133d58ee34cd2bcaa03.mp3', 16),
    ('我很开心能和你聊天。', 'Wǒ hěn kāixīn néng hé nǐ liáotiān.', 'Tôi rất vui được nói chuyện với bạn.', '[{"chinese":"开心","pinyin":"kāixīn","meaning_vi":"vui vẻ, hạnh phúc"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/lam-quen-ket-ban-150-cau/sentence-cdc3040d2f2f69f2470c979c.mp3', 17),
    ('请问，你是新来的吗？', 'Qǐngwèn, nǐ shì xīn lái de ma?', 'Xin hỏi bạn là người mới đến à?', '[{"chinese":"新来","pinyin":"xīn lái","meaning_vi":"mới đến"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/lam-quen-ket-ban-150-cau/sentence-c1ef31958e87cb132c38ed9f.mp3', 18),
    ('认识你我很高兴！', 'Rènshi nǐ wǒ hěn gāoxìng!', 'Gặp bạn tôi rất vui!', '[{"chinese":"认识","pinyin":"rènshi","meaning_vi":"làm quen, biết"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/lam-quen-ket-ban-150-cau/sentence-d595b34e6b82710ec54d941e.mp3', 19),
    ('你来自哪个城市？', 'Nǐ láizì nǎge chéngshì?', 'Bạn đến từ thành phố nào?', '[{"chinese":"城市","pinyin":"chéngshì","meaning_vi":"thành phố"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/lam-quen-ket-ban-150-cau/sentence-f5c13337010015e1d6d85d0b.mp3', 20),
    ('请问，你是哪国人？', 'Qǐngwèn, nǐ shì nǎ guó rén？', 'Xin hỏi, bạn là người nước nào?', '[{"chinese":"请问","pinyin":"qǐngwèn","meaning_vi":"xin hỏi"},{"chinese":"是哪国人","pinyin":"shì nǎ guó rén","meaning_vi":"là người nước nào"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/lam-quen-ket-ban-150-cau/sentence-23efef68e2c622a2e75c2e1b.mp3', 21),
    ('你现在住在什么地方？', 'Nǐ xiànzài zhù zài shénme dìfāng？', 'Bây giờ bạn sống ở đâu?', '[{"chinese":"现在","pinyin":"xiànzài","meaning_vi":"bây giờ"},{"chinese":"住在","pinyin":"zhù zài","meaning_vi":"sống ở"},{"chinese":"地方","pinyin":"dìfāng","meaning_vi":"địa phương, nơi chốn"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/lam-quen-ket-ban-150-cau/sentence-1c37e5de7733d714917769d1.mp3', 22),
    ('你已经在这里住了多长时间？', 'Nǐ yǐjīng zài zhèlǐ zhù le duō cháng shíjiān？', 'Bạn đã sống ở đây bao lâu rồi?', '[{"chinese":"已经","pinyin":"yǐjīng","meaning_vi":"đã, rồi"},{"chinese":"多长时间","pinyin":"duō cháng shíjiān","meaning_vi":"bao lâu"},{"chinese":"住","pinyin":"zhù","meaning_vi":"sống, ở"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/lam-quen-ket-ban-150-cau/sentence-67d13e0ae8cb08f25f0f5412.mp3', 23),
    ('你在哪个学校学习中文？', 'Nǐ zài nǎge xuéxiào xuéxí Zhōngwén？', 'Bạn học tiếng Trung ở trường nào?', '[{"chinese":"学校","pinyin":"xuéxiào","meaning_vi":"trường học"},{"chinese":"学习","pinyin":"xuéxí","meaning_vi":"học"},{"chinese":"中文","pinyin":"Zhōngwén","meaning_vi":"tiếng Trung"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/lam-quen-ket-ban-150-cau/sentence-19e8d52cb00f7b74a475ac32.mp3', 24),
    ('你学习的专业是什么？', 'Nǐ xuéxí de zhuānyè shì shénme？', 'Chuyên ngành bạn học là gì?', '[{"chinese":"专业","pinyin":"zhuānyè","meaning_vi":"chuyên ngành"},{"chinese":"学习","pinyin":"xuéxí","meaning_vi":"học"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/lam-quen-ket-ban-150-cau/sentence-8992ec4604a1584209b07332.mp3', 25),
    ('你做什么工作？', 'Nǐ zuò shénme gōngzuò？', 'Bạn làm nghề gì?', '[{"chinese":"工作","pinyin":"gōngzuò","meaning_vi":"công việc, nghề nghiệp"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/lam-quen-ket-ban-150-cau/sentence-3ef4eea6a85cd2a37edcf6ca.mp3', 26),
    ('我在一家大公司工作。', 'Wǒ zài yījiā dà gōngsī gōngzuò。', 'Tôi làm việc ở một công ty lớn.', '[{"chinese":"公司","pinyin":"gōngsī","meaning_vi":"công ty"},{"chinese":"工作","pinyin":"gōngzuò","meaning_vi":"làm việc"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/lam-quen-ket-ban-150-cau/sentence-2896d50b2d7ae252c45b7b27.mp3', 27),
    ('我来这座城市是为了工作。', 'Wǒ lái zhè zuò chéngshì shì wèile gōngzuò。', 'Tôi đến thành phố này để làm việc.', '[{"chinese":"城市","pinyin":"chéngshì","meaning_vi":"thành phố"},{"chinese":"为了","pinyin":"wèile","meaning_vi":"để, vì"},{"chinese":"工作","pinyin":"gōngzuò","meaning_vi":"công việc"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/lam-quen-ket-ban-150-cau/sentence-a411fe63780c0ff24e8dcb2e.mp3', 28),
    ('我在学校学习汉语已经一年了。', 'Wǒ zài xuéxiào xuéxí Hànyǔ yǐjīng yī nián le。', 'Tôi đã học tiếng Hán ở trường được một năm rồi.', '[{"chinese":"学校","pinyin":"xuéxiào","meaning_vi":"trường học"},{"chinese":"学习","pinyin":"xuéxí","meaning_vi":"học"},{"chinese":"已经","pinyin":"yǐjīng","meaning_vi":"đã rồi"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/lam-quen-ket-ban-150-cau/sentence-00ac6c9dc1c58e10f0a0412c.mp3', 29),
    ('你觉得这座城市和你的家乡有什么不同？', 'Nǐ juéde zhè zuò chéngshì hé nǐ de jiāxiāng yǒu shénme bùtóng？', 'Bạn cảm thấy thành phố này và quê bạn có gì khác nhau?', '[{"chinese":"城市","pinyin":"chéngshì","meaning_vi":"thành phố"},{"chinese":"家乡","pinyin":"jiāxiāng","meaning_vi":"quê hương"},{"chinese":"不同","pinyin":"bùtóng","meaning_vi":"khác nhau"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/lam-quen-ket-ban-150-cau/sentence-a657b8eef0c5b8c371dbf4b4.mp3', 30),
    ('我在这里工作已经三年了。', 'Wǒ zài zhèlǐ gōngzuò yǐjīng sān nián le。', 'Tôi đã làm việc ở đây được ba năm rồi.', '[{"chinese":"工作","pinyin":"gōngzuò","meaning_vi":"công việc"},{"chinese":"已经","pinyin":"yǐjīng","meaning_vi":"đã rồi"},{"chinese":"三年","pinyin":"sān nián","meaning_vi":"ba năm"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/lam-quen-ket-ban-150-cau/sentence-0b668f4695b8060912e7e0b3.mp3', 31),
    ('你的家乡风景优美吗？', 'Nǐ de jiāxiāng fēngjǐng yōuměi ma？', 'Quê bạn phong cảnh có đẹp không?', '[{"chinese":"家乡","pinyin":"jiāxiāng","meaning_vi":"quê hương"},{"chinese":"风景","pinyin":"fēngjǐng","meaning_vi":"phong cảnh"},{"chinese":"优美","pinyin":"yōuměi","meaning_vi":"đẹp, thanh nhã"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/lam-quen-ket-ban-150-cau/sentence-ccf16706020d728995e25dd0.mp3', 32),
    ('我毕业于本地大学，学的是计算机专业。', 'Wǒ bìyè yú běndì dàxué, xué de shì jìsuànjī zhuānyè。', 'Tôi tốt nghiệp đại học địa phương, chuyên ngành là công nghệ máy tính.', '[{"chinese":"毕业","pinyin":"bìyè","meaning_vi":"tốt nghiệp"},{"chinese":"本地","pinyin":"běndì","meaning_vi":"địa phương"},{"chinese":"专业","pinyin":"zhuānyè","meaning_vi":"chuyên ngành"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/lam-quen-ket-ban-150-cau/sentence-fecf6fe5416a344362ace768.mp3', 33),
    ('你喜欢你目前的工作环境吗？', 'Nǐ xǐhuan nǐ mùqián de gōngzuò huánjìng ma？', 'Bạn có thích môi trường làm việc hiện tại không?', '[{"chinese":"目前","pinyin":"mùqián","meaning_vi":"hiện tại"},{"chinese":"工作","pinyin":"gōngzuò","meaning_vi":"công việc"},{"chinese":"环境","pinyin":"huánjìng","meaning_vi":"môi trường"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/lam-quen-ket-ban-150-cau/sentence-021ca01b20229f6127e500d9.mp3', 34),
    ('你为什么选择这座城市生活？', 'Nǐ wèishénme xuǎnzé zhè zuò chéngshì shēnghuó？', 'Tại sao bạn chọn sống ở thành phố này?', '[{"chinese":"选择","pinyin":"xuǎnzé","meaning_vi":"chọn lựa"},{"chinese":"城市","pinyin":"chéngshì","meaning_vi":"thành phố"},{"chinese":"生活","pinyin":"shēnghuó","meaning_vi":"sống, sinh hoạt"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/lam-quen-ket-ban-150-cau/sentence-a66080a9c8004ad62b961ef7.mp3', 35),
    ('我喜欢这里的生活节奏，比家乡快很多。', 'Wǒ xǐhuan zhèlǐ de shēnghuó jiézòu, bǐ jiāxiāng kuài hěn duō。', 'Tôi thích nhịp sống ở đây, nhanh hơn quê nhiều.', '[{"chinese":"生活","pinyin":"shēnghuó","meaning_vi":"cuộc sống"},{"chinese":"节奏","pinyin":"jiézòu","meaning_vi":"nhịp điệu"},{"chinese":"家乡","pinyin":"jiāxiāng","meaning_vi":"quê hương"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/lam-quen-ket-ban-150-cau/sentence-8d8a5168d6ff135e7a0def5d.mp3', 36),
    ('你打算以后在哪里工作？', 'Nǐ dǎsuàn yǐhòu zài nǎlǐ gōngzuò？', 'Bạn dự định sau này làm việc ở đâu?', '[{"chinese":"打算","pinyin":"dǎsuàn","meaning_vi":"dự định"},{"chinese":"以后","pinyin":"yǐhòu","meaning_vi":"sau này"},{"chinese":"工作","pinyin":"gōngzuò","meaning_vi":"làm việc"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/lam-quen-ket-ban-150-cau/sentence-a19341e7b0d25df454645801.mp3', 37),
    ('你觉得学习中文难吗？', 'Nǐ juéde xuéxí Zhōngwén nán ma？', 'Bạn có thấy học tiếng Trung khó không?', '[{"chinese":"学习","pinyin":"xuéxí","meaning_vi":"học"},{"chinese":"中文","pinyin":"Zhōngwén","meaning_vi":"tiếng Trung"},{"chinese":"难","pinyin":"nán","meaning_vi":"khó"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/lam-quen-ket-ban-150-cau/sentence-44a6657e5db37a4fc3f6e398.mp3', 38),
    ('这附近有你喜欢的餐馆吗？', 'Zhè fùjìn yǒu nǐ xǐhuan de cānguǎn ma？', 'Gần đây có nhà hàng mà bạn thích không?', '[{"chinese":"附近","pinyin":"fùjìn","meaning_vi":"gần đây"},{"chinese":"喜欢","pinyin":"xǐhuan","meaning_vi":"thích"},{"chinese":"餐馆","pinyin":"cānguǎn","meaning_vi":"nhà hàng"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/lam-quen-ket-ban-150-cau/sentence-4fe5e1d78ac02950cde65f80.mp3', 39),
    ('我想了解你的工作内容。', 'Wǒ xiǎng liǎojiě nǐ de gōngzuò nèiróng。', 'Tôi muốn tìm hiểu nội dung công việc của bạn.', '[{"chinese":"了解","pinyin":"liǎojiě","meaning_vi":"hiểu, tìm hiểu"},{"chinese":"工作","pinyin":"gōngzuò","meaning_vi":"công việc"},{"chinese":"内容","pinyin":"nèiróng","meaning_vi":"nội dung"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/lam-quen-ket-ban-150-cau/sentence-02a0b39aee452a065e1f3765.mp3', 40),
    ('你喜欢什么样的音乐？', 'Nǐ xǐhuān shénme yàng de yīnyuè？', 'Bạn thích thể loại âm nhạc nào?', '[{"chinese":"喜欢","pinyin":"xǐhuān","meaning_vi":"thích"},{"chinese":"音乐","pinyin":"yīnyuè","meaning_vi":"âm nhạc"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/lam-quen-ket-ban-150-cau/sentence-dc09925bccbc3f0c5a7b288c.mp3', 41),
    ('我最喜欢听流行音乐和摇滚乐。', 'Wǒ zuì xǐhuān tīng liúxíng yīnyuè hé yáogǔn yuè。', 'Tôi thích nghe nhạc pop và nhạc rock nhất.', '[{"chinese":"最喜欢","pinyin":"zuì xǐhuān","meaning_vi":"thích nhất"},{"chinese":"流行音乐","pinyin":"liúxíng yīnyuè","meaning_vi":"nhạc pop"},{"chinese":"摇滚乐","pinyin":"yáogǔn yuè","meaning_vi":"nhạc rock"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/lam-quen-ket-ban-150-cau/sentence-fa7e6f02f8f507021e24dee0.mp3', 42),
    ('我周末常常去打篮球锻炼身体。', 'Wǒ zhōumò chángcháng qù dǎ lánqiú duànliàn shēntǐ。', 'Cuối tuần tôi thường đi chơi bóng rổ để rèn luyện cơ thể.', '[{"chinese":"周末","pinyin":"zhōumò","meaning_vi":"cuối tuần"},{"chinese":"打篮球","pinyin":"dǎ lánqiú","meaning_vi":"chơi bóng rổ"},{"chinese":"锻炼","pinyin":"duànliàn","meaning_vi":"rèn luyện"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/lam-quen-ket-ban-150-cau/sentence-3c55f616584f7233a25bac9d.mp3', 43),
    ('你会做什么拿手的菜？', 'Nǐ huì zuò shénme náshǒu de cài？', 'Bạn có thể nấu món ăn gì ngon nhất?', '[{"chinese":"拿手","pinyin":"náshǒu","meaning_vi":"giỏi, thành thạo"},{"chinese":"菜","pinyin":"cài","meaning_vi":"món ăn"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/lam-quen-ket-ban-150-cau/sentence-6a58841b99203e742f684188.mp3', 44),
    ('我很喜欢旅行，尤其喜欢去海边。', 'Wǒ hěn xǐhuān lǚxíng，yóuqí xǐhuān qù hǎibiān。', 'Tôi rất thích đi du lịch, đặc biệt thích đến biển.', '[{"chinese":"旅行","pinyin":"lǚxíng","meaning_vi":"du lịch"},{"chinese":"尤其","pinyin":"yóuqí","meaning_vi":"đặc biệt"},{"chinese":"海边","pinyin":"hǎibiān","meaning_vi":"bên bờ biển"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/lam-quen-ket-ban-150-cau/sentence-2f240fe2b6d212b5244df3c2.mp3', 45),
    ('你喜欢用相机拍照吗？', 'Nǐ xǐhuān yòng xiàngjī pāizhào ma？', 'Bạn thích dùng máy ảnh để chụp hình không?', '[{"chinese":"相机","pinyin":"xiàngjī","meaning_vi":"máy ảnh"},{"chinese":"拍照","pinyin":"pāizhào","meaning_vi":"chụp ảnh"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/lam-quen-ket-ban-150-cau/sentence-86c727595bfa4fca6ccd7d6f.mp3', 46),
    ('你养过宠物吗？哪种宠物？', 'Nǐ yǎng guò chǒngwù ma？Nǎ zhǒng chǒngwù？', 'Bạn đã từng nuôi thú cưng chưa? Là loại nào?', '[{"chinese":"养","pinyin":"yǎng","meaning_vi":"nuôi"},{"chinese":"宠物","pinyin":"chǒngwù","meaning_vi":"thú cưng"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/lam-quen-ket-ban-150-cau/sentence-4c2dacf57eb7b25d1b4e613c.mp3', 47),
    ('周末你通常做什么休闲活动？', 'Zhōumò nǐ tōngcháng zuò shénme xiūxián huódòng？', 'Cuối tuần bạn thường làm hoạt động giải trí gì?', '[{"chinese":"通常","pinyin":"tōngcháng","meaning_vi":"thường"},{"chinese":"休闲活动","pinyin":"xiūxián huódòng","meaning_vi":"hoạt động giải trí"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/lam-quen-ket-ban-150-cau/sentence-1602d5e67d7167a475544ae1.mp3', 48),
    ('我喜欢听轻音乐放松心情。', 'Wǒ xǐhuān tīng qīng yīnyuè fàngsōng xīnqíng。', 'Tôi thích nghe nhạc nhẹ để thư giãn tâm trạng.', '[{"chinese":"轻音乐","pinyin":"qīng yīnyuè","meaning_vi":"nhạc nhẹ"},{"chinese":"放松","pinyin":"fàngsōng","meaning_vi":"thư giãn"},{"chinese":"心情","pinyin":"xīnqíng","meaning_vi":"tâm trạng"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/lam-quen-ket-ban-150-cau/sentence-c6e507a9455d779b29159110.mp3', 49),
    ('你平时喜欢运动吗？哪种运动？', 'Nǐ píngshí xǐhuān yùndòng ma？Nǎ zhǒng yùndòng？', 'Bạn thường thích vận động không? Môn thể thao nào?', '[{"chinese":"运动","pinyin":"yùndòng","meaning_vi":"vận động, thể thao"},{"chinese":"种","pinyin":"zhǒng","meaning_vi":"loại"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/lam-quen-ket-ban-150-cau/sentence-44136470cbe2c0b10ed9dbae.mp3', 50),
    ('我朋友喜欢养狗，它非常可爱。', 'Wǒ péngyǒu xǐhuān yǎng gǒu，tā fēicháng kě''ài。', 'Bạn tôi thích nuôi chó, nó rất dễ thương.', '[{"chinese":"养","pinyin":"yǎng","meaning_vi":"nuôi"},{"chinese":"非常","pinyin":"fēicháng","meaning_vi":"rất"},{"chinese":"可爱","pinyin":"kě''ài","meaning_vi":"dễ thương"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/lam-quen-ket-ban-150-cau/sentence-49ec7b5fea527b6a2c7b3bd2.mp3', 51),
    ('你喜欢在家做饭还是出去吃？', 'Nǐ xǐhuān zài jiā zuò fàn háishì chūqù chī？', 'Bạn thích nấu ăn ở nhà hay ra ngoài ăn?', '[{"chinese":"做饭","pinyin":"zuò fàn","meaning_vi":"nấu ăn"},{"chinese":"出去","pinyin":"chūqù","meaning_vi":"ra ngoài"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/lam-quen-ket-ban-150-cau/sentence-0e612cdf865af79f30348e59.mp3', 52),
    ('我喜欢和朋友一起去公园散步。', 'Wǒ xǐhuān hé péngyǒu yìqǐ qù gōngyuán sànbù。', 'Tôi thích cùng bạn bè đi dạo ở công viên.', '[{"chinese":"公园","pinyin":"gōngyuán","meaning_vi":"công viên"},{"chinese":"散步","pinyin":"sànbù","meaning_vi":"đi dạo"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/lam-quen-ket-ban-150-cau/sentence-a25c12caf9f67b5354f9dd16.mp3', 53),
    ('你喜欢看书吗？最近读了什么好书？', 'Nǐ xǐhuān kàn shū ma？Zuìjìn dúle shénme hǎoshū？', 'Bạn thích đọc sách không? Gần đây đã đọc cuốn sách hay nào?', '[{"chinese":"看书","pinyin":"kàn shū","meaning_vi":"đọc sách"},{"chinese":"最近","pinyin":"zuìjìn","meaning_vi":"gần đây"},{"chinese":"好书","pinyin":"hǎoshū","meaning_vi":"cuốn sách hay"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/lam-quen-ket-ban-150-cau/sentence-2e8b3aeee5ec6be110abaef1.mp3', 54),
    ('周末我喜欢去郊外骑自行车。', 'Zhōumò wǒ xǐhuān qù jiāowài qí zìxíngchē。', 'Cuối tuần tôi thích đi ngoại ô đạp xe đạp.', '[{"chinese":"周末","pinyin":"zhōumò","meaning_vi":"cuối tuần"},{"chinese":"郊外","pinyin":"jiāowài","meaning_vi":"ngoại ô"},{"chinese":"自行车","pinyin":"zìxíngchē","meaning_vi":"xe đạp"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/lam-quen-ket-ban-150-cau/sentence-ec94c1ec1ac351968e10ef5d.mp3', 55),
    ('我喜欢在家看电视剧放松。', 'Wǒ xǐhuān zài jiā kàn diànshìjù fàngsōng。', 'Tôi thích xem phim truyền hình ở nhà để thư giãn.', '[{"chinese":"电视剧","pinyin":"diànshìjù","meaning_vi":"phim truyền hình"},{"chinese":"放松","pinyin":"fàngsōng","meaning_vi":"thư giãn"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/lam-quen-ket-ban-150-cau/sentence-90f538352357b84384ccd70c.mp3', 56),
    ('你有喜欢的运动队或者运动员吗？', 'Nǐ yǒu xǐhuān de yùndòng duì huòzhě yùndòngyuán ma？', 'Bạn có đội thể thao hoặc vận động viên yêu thích không?', '[{"chinese":"运动队","pinyin":"yùndòng duì","meaning_vi":"đội thể thao"},{"chinese":"运动员","pinyin":"yùndòngyuán","meaning_vi":"vận động viên"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/lam-quen-ket-ban-150-cau/sentence-5dabc4ac436fee195622257f.mp3', 57),
    ('我很喜欢尝试不同国家的美食。', 'Wǒ hěn xǐhuān chángshì bùtóng guójiā de měishí。', 'Tôi rất thích thử các món ăn ngon của các quốc gia khác nhau.', '[{"chinese":"尝试","pinyin":"chángshì","meaning_vi":"thử"},{"chinese":"不同","pinyin":"bùtóng","meaning_vi":"khác nhau"},{"chinese":"美食","pinyin":"měishí","meaning_vi":"món ăn ngon"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/lam-quen-ket-ban-150-cau/sentence-061fdd86ee156f77495c4997.mp3', 58),
    ('你喜欢去现场听音乐会吗？', 'Nǐ xǐhuan qù xiànchǎng tīng yīnyuèhuì ma?', 'Bạn có thích đến nghe hòa nhạc trực tiếp không?', '[{"chinese":"现场","pinyin":"xiànchǎng","meaning_vi":"trực tiếp, tại chỗ"},{"chinese":"音乐会","pinyin":"yīnyuèhuì","meaning_vi":"buổi hòa nhạc"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/lam-quen-ket-ban-150-cau/sentence-50d473d3ab736eb8f9d07497.mp3', 59),
    ('我喜欢拍自然风光的照片。', 'Wǒ xǐhuān pāi zìrán fēngguāng de zhàopiàn。', 'Tôi thích chụp ảnh phong cảnh thiên nhiên.', '[{"chinese":"自然","pinyin":"zìrán","meaning_vi":"thiên nhiên"},{"chinese":"风光","pinyin":"fēngguāng","meaning_vi":"phong cảnh"},{"chinese":"照片","pinyin":"zhàopiàn","meaning_vi":"ảnh"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/lam-quen-ket-ban-150-cau/sentence-4dc627db7a79dfb81fa2c593.mp3', 60),
    ('我经常和朋友一起打羽毛球。', 'Wǒ jīngcháng hé péngyǒu yìqǐ dǎ yǔmáoqiú。', 'Tôi thường xuyên chơi cầu lông cùng bạn bè.', '[{"chinese":"经常","pinyin":"jīngcháng","meaning_vi":"thường xuyên"},{"chinese":"羽毛球","pinyin":"yǔmáoqiú","meaning_vi":"cầu lông"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/lam-quen-ket-ban-150-cau/sentence-09b3853ada65b3b644cd0997.mp3', 61),
    ('你喜欢尝试新的游戏吗？', 'Nǐ xǐhuān chángshì xīn de yóuxì ma？', 'Bạn có thích thử những trò chơi mới không?', '[{"chinese":"尝试","pinyin":"chángshì","meaning_vi":"thử"},{"chinese":"游戏","pinyin":"yóuxì","meaning_vi":"trò chơi"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/lam-quen-ket-ban-150-cau/sentence-c45c3c4dfc8b02dae7cd7e6d.mp3', 62),
    ('我喜欢在周末做手工艺品放松。', 'Wǒ xǐhuān zài zhōumò zuò shǒugōng yìpǐn fàngsōng。', 'Tôi thích làm đồ thủ công vào cuối tuần để thư giãn.', '[{"chinese":"手工艺品","pinyin":"shǒugōng yìpǐn","meaning_vi":"đồ thủ công"},{"chinese":"周末","pinyin":"zhōumò","meaning_vi":"cuối tuần"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/lam-quen-ket-ban-150-cau/sentence-6bea2fec63ff0556fb027101.mp3', 63),
    ('你喜欢听什么类型的音乐？', 'Nǐ xǐhuān tīng shénme lèixíng de yīnyuè？', 'Bạn thích nghe loại nhạc gì?', '[{"chinese":"类型","pinyin":"lèixíng","meaning_vi":"loại hình, thể loại"},{"chinese":"音乐","pinyin":"yīnyuè","meaning_vi":"âm nhạc"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/lam-quen-ket-ban-150-cau/sentence-d196f55ce6e5641de8ea9391.mp3', 64),
    ('你平时喜欢做什么运动？', 'Nǐ píngshí xǐhuān zuò shénme yùndòng？', 'Bạn thường thích chơi môn thể thao gì?', '[{"chinese":"平时","pinyin":"píngshí","meaning_vi":"thường ngày"},{"chinese":"运动","pinyin":"yùndòng","meaning_vi":"thể thao, vận động"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/lam-quen-ket-ban-150-cau/sentence-342e036b56b3f90cab3e643b.mp3', 65),
    ('你学习中文多长时间了？', 'Nǐ xuéxí zhōngwén duō cháng shíjiān le?', 'Bạn học tiếng Trung bao lâu rồi?', '[{"chinese":"学习","pinyin":"xuéxí","meaning_vi":"học tập"},{"chinese":"多长时间","pinyin":"duō cháng shíjiān","meaning_vi":"bao lâu"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/lam-quen-ket-ban-150-cau/sentence-af1e658ee6ad84f34733bf07.mp3', 66),
    ('我学习中文是为了工作需要。', 'Wǒ xuéxí zhōngwén shì wèile gōngzuò xūyào.', 'Tôi học tiếng Trung là vì nhu cầu công việc.', '[{"chinese":"工作","pinyin":"gōngzuò","meaning_vi":"công việc"},{"chinese":"需要","pinyin":"xūyào","meaning_vi":"nhu cầu, cần"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/lam-quen-ket-ban-150-cau/sentence-011e82a6a07647b598671214.mp3', 67),
    ('你现在的中文水平怎么样？', 'Nǐ xiànzài de zhōngwén shuǐpíng zěnmeyàng?', 'Trình độ tiếng Trung hiện tại của bạn thế nào?', '[{"chinese":"水平","pinyin":"shuǐpíng","meaning_vi":"trình độ"},{"chinese":"现在","pinyin":"xiànzài","meaning_vi":"hiện tại"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/lam-quen-ket-ban-150-cau/sentence-b2c47cb87a1e733b8fadf259.mp3', 68),
    ('我觉得听力是学习中最难的部分。', 'Wǒ juéde tīnglì shì xuéxí zhōng zuì nán de bùfen.', 'Tôi cảm thấy kỹ năng nghe là phần khó nhất khi học.', '[{"chinese":"听力","pinyin":"tīnglì","meaning_vi":"kỹ năng nghe"},{"chinese":"部分","pinyin":"bùfen","meaning_vi":"phần, bộ phận"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/lam-quen-ket-ban-150-cau/sentence-7b8f665f80b83f3a6eeca50c.mp3', 69),
    ('每天我都会花时间练习口语。', 'Měitiān wǒ dūhuì huā shíjiān liànxí kǒuyǔ.', 'Mỗi ngày tôi đều dành thời gian luyện nói.', '[{"chinese":"每天","pinyin":"měitiān","meaning_vi":"mỗi ngày"},{"chinese":"练习","pinyin":"liànxí","meaning_vi":"luyện tập"},{"chinese":"口语","pinyin":"kǒuyǔ","meaning_vi":"nói, nói chuyện"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/lam-quen-ket-ban-150-cau/sentence-ac272b854462880ec6ac3b08.mp3', 70),
    ('你可以帮我纠正中文发音吗？', 'Nǐ kěyǐ bāng wǒ jiūzhèng zhōngwén fāyīn ma?', 'Bạn có thể giúp tôi sửa phát âm tiếng Trung được không?', '[{"chinese":"纠正","pinyin":"jiūzhèng","meaning_vi":"sửa chữa, chỉnh sửa"},{"chinese":"发音","pinyin":"fāyīn","meaning_vi":"phát âm"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/lam-quen-ket-ban-150-cau/sentence-ae6f384f8ae0095fa3f3b1b4.mp3', 71),
    ('我们可以一起练习中文会话。', 'Wǒmen kěyǐ yìqǐ liànxí zhōngwén huìhuà.', 'Chúng ta có thể cùng nhau luyện tập hội thoại tiếng Trung.', '[{"chinese":"一起","pinyin":"yìqǐ","meaning_vi":"cùng nhau"},{"chinese":"会话","pinyin":"huìhuà","meaning_vi":"hội thoại"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/lam-quen-ket-ban-150-cau/sentence-6d7086643a6794901de30e44.mp3', 72),
    ('你喜欢用什么方法学习中文？', 'Nǐ xǐhuan yòng shénme fāngfǎ xuéxí zhōngwén?', 'Bạn thích dùng phương pháp gì để học tiếng Trung?', '[{"chinese":"方法","pinyin":"fāngfǎ","meaning_vi":"phương pháp"},{"chinese":"喜欢","pinyin":"xǐhuan","meaning_vi":"thích"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/lam-quen-ket-ban-150-cau/sentence-8b70baa32a312885533f88b7.mp3', 73),
    ('我用手机应用来练习听力。', 'Wǒ yòng shǒujī yìngyòng lái liànxí tīnglì.', 'Tôi sử dụng ứng dụng điện thoại để luyện nghe.', '[{"chinese":"应用","pinyin":"yìngyòng","meaning_vi":"ứng dụng"},{"chinese":"听力","pinyin":"tīnglì","meaning_vi":"kỹ năng nghe"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/lam-quen-ket-ban-150-cau/sentence-98b7f5641d361e7bc194db10.mp3', 74),
    ('我们可以互相帮助提高语言能力。', 'Wǒmen kěyǐ hùxiāng bāngzhù tígāo yǔyán nénglì.', 'Chúng ta có thể giúp đỡ nhau nâng cao khả năng ngôn ngữ.', '[{"chinese":"互相","pinyin":"hùxiāng","meaning_vi":"lẫn nhau"},{"chinese":"提高","pinyin":"tígāo","meaning_vi":"nâng cao"},{"chinese":"能力","pinyin":"nénglì","meaning_vi":"khả năng"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/lam-quen-ket-ban-150-cau/sentence-f7586dfdc5b874c67dfc3109.mp3', 75),
    ('你在学习中文时遇到什么困难？', 'Nǐ zài xuéxí zhōngwén shí yù dào shénme kùnnan?', 'Khi học tiếng Trung bạn gặp khó khăn gì?', '[{"chinese":"困难","pinyin":"kùnnan","meaning_vi":"khó khăn"},{"chinese":"遇到","pinyin":"yùdào","meaning_vi":"gặp phải"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/lam-quen-ket-ban-150-cau/sentence-a950a28f1353e5ad79beffba.mp3', 76),
    ('你想不想和我一起学习中文？', 'Nǐ xiǎng bù xiǎng hé wǒ yìqǐ xuéxí zhōngwén?', 'Bạn có muốn học tiếng Trung cùng tôi không?', '[{"chinese":"学习","pinyin":"xuéxí","meaning_vi":"học tập"},{"chinese":"一起","pinyin":"yìqǐ","meaning_vi":"cùng nhau"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/lam-quen-ket-ban-150-cau/sentence-cb3e5b37f790f503d422a70c.mp3', 77),
    ('你平时怎么练习中文发音？', 'Nǐ píngshí zěnme liànxí zhōngwén fāyīn?', 'Bạn thường luyện phát âm tiếng Trung như thế nào?', '[{"chinese":"练习","pinyin":"liànxí","meaning_vi":"luyện tập"},{"chinese":"发音","pinyin":"fāyīn","meaning_vi":"phát âm"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/lam-quen-ket-ban-150-cau/sentence-6c23437ac8db40e2f7fc00f9.mp3', 78),
    ('我们可以交换语言学习经验。', 'Wǒmen kěyǐ jiāohuàn yǔyán xuéxí jīngyàn.', 'Chúng ta có thể trao đổi kinh nghiệm học ngôn ngữ.', '[{"chinese":"交换","pinyin":"jiāohuàn","meaning_vi":"trao đổi"},{"chinese":"经验","pinyin":"jīngyàn","meaning_vi":"kinh nghiệm"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/lam-quen-ket-ban-150-cau/sentence-e70e277bf718dc9a46e59f78.mp3', 79),
    ('你觉得中文写作难吗？', 'Nǐ juéde zhōngwén xiězuò nán ma?', 'Bạn thấy việc viết tiếng Trung có khó không?', '[{"chinese":"写作","pinyin":"xiězuò","meaning_vi":"viết văn"},{"chinese":"难","pinyin":"nán","meaning_vi":"khó"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/lam-quen-ket-ban-150-cau/sentence-74d499037596b953f04fede7.mp3', 80),
    ('可以加你的微信吗？我想和你保持联系。', 'Kěyǐ jiā nǐ de Wēixìn ma? Wǒ xiǎng hé nǐ bǎochí liánxì.', 'Mình có thể thêm WeChat của bạn không? Mình muốn giữ liên lạc với bạn.', '[{"chinese":"保持","pinyin":"bǎochí","meaning_vi":"giữ, duy trì"},{"chinese":"联系","pinyin":"liánxì","meaning_vi":"liên lạc, liên hệ"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/lam-quen-ket-ban-150-cau/sentence-ff46bf33ed967a37349909bc.mp3', 81),
    ('这是我的微信二维码，你可以扫一扫。', 'Zhè shì wǒ de Wēixìn èrwéimǎ, nǐ kěyǐ sǎo yī sǎo.', 'Đây là mã QR WeChat của mình, bạn có thể quét thử nhé.', '[{"chinese":"二维码","pinyin":"èrwéimǎ","meaning_vi":"mã QR"},{"chinese":"扫一扫","pinyin":"sǎo yī sǎo","meaning_vi":"quét một cái"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/lam-quen-ket-ban-150-cau/sentence-0103b71a4d77baf375b4fd27.mp3', 82),
    ('我可以扫一下你的微信二维码吗？', 'Wǒ kěyǐ sǎo yíxià nǐ de Wēixìn èrwéimǎ ma?', 'Mình có thể quét mã QR WeChat của bạn không?', '[{"chinese":"扫","pinyin":"sǎo","meaning_vi":"quét"},{"chinese":"二维码","pinyin":"èrwéimǎ","meaning_vi":"mã QR"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/lam-quen-ket-ban-150-cau/sentence-9e3594e2bf78d8017f99e647.mp3', 83),
    ('我已经添加了你的微信，请查收消息。', 'Wǒ yǐjīng tiānjiā le nǐ de Wēixìn, qǐng cháshōu xiāoxī.', 'Mình đã thêm WeChat của bạn rồi, vui lòng kiểm tra tin nhắn.', '[{"chinese":"添加","pinyin":"tiānjiā","meaning_vi":"thêm vào"},{"chinese":"消息","pinyin":"xiāoxī","meaning_vi":"tin nhắn, tin tức"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/lam-quen-ket-ban-150-cau/sentence-48b3fdf0298746f9528c5e62.mp3', 84),
    ('请问可以留一下你的电话号码吗？', 'Qǐngwèn kěyǐ liú yīxià nǐ de diànhuà hàomǎ ma?', 'Bạn có thể để lại số điện thoại của bạn được không?', '[{"chinese":"电话号码","pinyin":"diànhuà hàomǎ","meaning_vi":"số điện thoại"},{"chinese":"留","pinyin":"liú","meaning_vi":"để lại, giữ lại"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/lam-quen-ket-ban-150-cau/sentence-d8ce03c6d0f90712628210c7.mp3', 85),
    ('我刚发了一条信息，你收到了吗？', 'Wǒ gāng fā le yī tiáo xìnxī, nǐ shōudào le ma?', 'Mình vừa mới gửi một tin nhắn, bạn đã nhận được chưa?', '[{"chinese":"信息","pinyin":"xìnxī","meaning_vi":"tin nhắn, thông tin"},{"chinese":"收到","pinyin":"shōudào","meaning_vi":"nhận được"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/lam-quen-ket-ban-150-cau/sentence-5c261b481a72e3b63fa6c4b2.mp3', 86),
    ('我找不到你的微信账号，可以再告诉我吗？', 'Wǒ zhǎo bù dào nǐ de Wēixìn zhànghào, kěyǐ zài gàosù wǒ ma?', 'Mình không tìm thấy tài khoản WeChat của bạn, bạn có thể nói lại cho mình không?', '[{"chinese":"找不到","pinyin":"zhǎo bù dào","meaning_vi":"không tìm thấy"},{"chinese":"账号","pinyin":"zhànghào","meaning_vi":"tài khoản"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/lam-quen-ket-ban-150-cau/sentence-934307e5e1c7ed8890f8a6c6.mp3', 87),
    ('如果你换了微信，记得告诉我新的联系方式。', 'Rúguǒ nǐ huàn le Wēixìn, jìdé gàosù wǒ xīn de liánxì fāngshì.', 'Nếu bạn đổi WeChat thì nhớ nói cho mình thông tin liên lạc mới nhé.', '[{"chinese":"换","pinyin":"huàn","meaning_vi":"đổi, thay"},{"chinese":"联系方式","pinyin":"liánxì fāngshì","meaning_vi":"cách thức liên lạc"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/lam-quen-ket-ban-150-cau/sentence-7904dc4845e58ef46dc9631f.mp3', 88),
    ('我们改天再联系，好吗？', 'Wǒmen gǎitiān zài liánxì, hǎo ma?', 'Chúng ta hẹn hôm khác liên lạc nhé, được không?', '[{"chinese":"改天","pinyin":"gǎitiān","meaning_vi":"hẹn hôm khác"},{"chinese":"联系","pinyin":"liánxì","meaning_vi":"liên lạc"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/lam-quen-ket-ban-150-cau/sentence-fab15d1b356eb4193d1a003f.mp3', 89),
    ('谢谢你，以后我们常联系吧。', 'Xièxie nǐ, yǐhòu wǒmen cháng liánxì ba.', 'Cảm ơn bạn, sau này chúng ta thường xuyên liên lạc nhé.', '[{"chinese":"联系","pinyin":"liánxì","meaning_vi":"liên lạc"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/lam-quen-ket-ban-150-cau/sentence-e8e60365ac742b0a5f1b9853.mp3', 90),
    ('你的微信名字是什么，我想搜索一下。', 'Nǐ de Wēixìn míngzì shì shénme, wǒ xiǎng sōusuǒ yīxià.', 'Tên WeChat của bạn là gì, mình muốn tìm kiếm một chút.', '[{"chinese":"名字","pinyin":"míngzì","meaning_vi":"tên"},{"chinese":"搜索","pinyin":"sōusuǒ","meaning_vi":"tìm kiếm"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/lam-quen-ket-ban-150-cau/sentence-8ddb0e3e5ea6dafc987da8ff.mp3', 91),
    ('你方便告诉我你的手机号吗？', 'Nǐ fāngbiàn gàosù wǒ nǐ de shǒujī hào ma?', 'Bạn tiện cho mình biết số điện thoại di động của bạn được không?', '[{"chinese":"方便","pinyin":"fāngbiàn","meaning_vi":"tiện lợi, tiện"},{"chinese":"手机号","pinyin":"shǒujī hào","meaning_vi":"số điện thoại di động"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/lam-quen-ket-ban-150-cau/sentence-a330423376536e2e041a1c5f.mp3', 92),
    ('请问，我可以给你发一条消息吗？', 'Qǐngwèn, wǒ kěyǐ gěi nǐ fā yī tiáo xiāoxi ma?', 'Xin hỏi, mình có thể gửi cho bạn một tin nhắn không?', '[{"chinese":"消息","pinyin":"xiāoxi","meaning_vi":"tin nhắn"},{"chinese":"发","pinyin":"fā","meaning_vi":"gửi"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/lam-quen-ket-ban-150-cau/sentence-cbe2dc9003fd0bd5f8c3c8d7.mp3', 93),
    ('我已经加了你的微信，期待以后多聊天。', 'Wǒ yǐjīng jiā le nǐ de Wēixìn, qídài yǐhòu duō liáotiān.', 'Mình đã thêm WeChat của bạn rồi, mong sau này được trò chuyện nhiều hơn.', '[{"chinese":"期待","pinyin":"qídài","meaning_vi":"mong đợi"},{"chinese":"聊天","pinyin":"liáotiān","meaning_vi":"trò chuyện"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/lam-quen-ket-ban-150-cau/sentence-fbb6dbbcded268f33c8ec808.mp3', 94),
    ('如果方便，我们可以互相交换联系方式。', 'Rúguǒ fāngbiàn, wǒmen kěyǐ hùxiāng jiāohuàn liánxì fāngshì.', 'Nếu tiện thì chúng ta có thể trao đổi thông tin liên lạc với nhau.', '[{"chinese":"互相","pinyin":"hùxiāng","meaning_vi":"lẫn nhau, tương hỗ"},{"chinese":"交换","pinyin":"jiāohuàn","meaning_vi":"trao đổi"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/lam-quen-ket-ban-150-cau/sentence-20325507a82f0bff8b5a969c.mp3', 95),
    ('我们一起去吃饭，好吗？', 'Wǒmen yīqǐ qù chīfàn, hǎo ma?', 'Chúng ta cùng đi ăn nhé?', '[{"chinese":"吃饭","pinyin":"chīfàn","meaning_vi":"ăn cơm, ăn"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/lam-quen-ket-ban-150-cau/sentence-cde86734d8e6b731b02a0fdd.mp3', 96),
    ('周末一起去喝咖啡怎么样？', 'Zhōumò yīqǐ qù hē kāfēi zěnmeyàng?', 'Cuối tuần cùng đi uống cà phê thế nào?', '[{"chinese":"周末","pinyin":"zhōumò","meaning_vi":"cuối tuần"},{"chinese":"喝","pinyin":"hē","meaning_vi":"uống"},{"chinese":"咖啡","pinyin":"kāfēi","meaning_vi":"cà phê"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/lam-quen-ket-ban-150-cau/sentence-e536c021d39a815de0883093.mp3', 97),
    ('下午我们一起去公园散步吧。', 'Xiàwǔ wǒmen yīqǐ qù gōngyuán sànbù ba.', 'Chiều nay chúng ta cùng đi dạo công viên nhé.', '[{"chinese":"散步","pinyin":"sànbù","meaning_vi":"đi dạo"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/lam-quen-ket-ban-150-cau/sentence-b2fa0507fa8470f1a1c02289.mp3', 98),
    ('周末你想不想一起打篮球？', 'Zhōumò nǐ xiǎng bu xiǎng yīqǐ dǎ lánqiú?', 'Cuối tuần bạn có muốn cùng chơi bóng rổ không?', '[{"chinese":"打篮球","pinyin":"dǎ lánqiú","meaning_vi":"chơi bóng rổ"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/lam-quen-ket-ban-150-cau/sentence-bad74a4667b92be81c28da30.mp3', 99),
    ('你这个周末有空吗？', 'Nǐ zhège zhōumò yǒu kòng ma?', 'Cuối tuần này bạn có rảnh không?', '[{"chinese":"周末","pinyin":"zhōumò","meaning_vi":"cuối tuần"},{"chinese":"有空","pinyin":"yǒu kòng","meaning_vi":"có thời gian, rảnh"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/lam-quen-ket-ban-150-cau/sentence-d6e50e4dfb0c333476984f04.mp3', 100),
    ('你想去哪个餐厅吃饭？', 'Nǐ xiǎng qù nǎge cāntīng chīfàn?', 'Bạn muốn đến nhà hàng nào để ăn?', '[{"chinese":"餐厅","pinyin":"cāntīng","meaning_vi":"nhà hàng"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/lam-quen-ket-ban-150-cau/sentence-9e883b48272442e3dc92796b.mp3', 101),
    ('我们几点见面比较合适？', 'Wǒmen jǐ diǎn jiànmiàn bǐjiào héshì?', 'Chúng ta gặp nhau lúc mấy giờ thì hợp lý hơn?', '[{"chinese":"见面","pinyin":"jiànmiàn","meaning_vi":"gặp mặt"},{"chinese":"合适","pinyin":"héshì","meaning_vi":"phù hợp"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/lam-quen-ket-ban-150-cau/sentence-a2b682d7163c045f57d6be07.mp3', 102),
    ('我有点事，能不能改天再见？', 'Wǒ yǒudiǎn shì, néng bu néng gǎitiān zài jiàn?', 'Tôi có chút việc, có thể hẹn lại ngày khác gặp không?', '[{"chinese":"改天","pinyin":"gǎitiān","meaning_vi":"đổi ngày, ngày khác"},{"chinese":"再见","pinyin":"zàijiàn","meaning_vi":"gặp lại, tạm biệt"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/lam-quen-ket-ban-150-cau/sentence-99ab3fc4ebe7e4d2b5235879.mp3', 103),
    ('我们约好的时间还合适吗？', 'Wǒmen yuē hǎo de shíjiān hái héshì ma?', 'Thời gian chúng ta đã hẹn vẫn hợp lý chứ?', '[{"chinese":"约好","pinyin":"yuē hǎo","meaning_vi":"hẹn trước"},{"chinese":"时间","pinyin":"shíjiān","meaning_vi":"thời gian"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/lam-quen-ket-ban-150-cau/sentence-815cea51b84ee2286fe947a0.mp3', 104),
    ('今天晚上一起去吃火锅吧。', 'Jīntiān wǎnshàng yīqǐ qù chī huǒguō ba.', 'Tối nay cùng đi ăn lẩu nhé.', '[{"chinese":"火锅","pinyin":"huǒguō","meaning_vi":"lẩu"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/lam-quen-ket-ban-150-cau/sentence-8289b0c221a01c57c30cb670.mp3', 105),
    ('你喜欢喝什么咖啡？我们可以一起去喝。', 'Nǐ xǐhuān hē shénme kāfēi? Wǒmen kěyǐ yīqǐ qù hē.', 'Bạn thích uống loại cà phê nào? Chúng ta có thể cùng đi uống.', '[{"chinese":"喜欢","pinyin":"xǐhuān","meaning_vi":"thích"},{"chinese":"咖啡","pinyin":"kāfēi","meaning_vi":"cà phê"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/lam-quen-ket-ban-150-cau/sentence-7b5c9f2b4c1f2acbae1ced78.mp3', 106),
    ('晚上散步可以放松心情，你想去吗？', 'Wǎnshàng sànbù kěyǐ fàngsōng xīnqíng, nǐ xiǎng qù ma?', 'Tối đi dạo có thể thư giãn tâm trạng, bạn có muốn đi không?', '[{"chinese":"散步","pinyin":"sànbù","meaning_vi":"đi dạo"},{"chinese":"放松","pinyin":"fàngsōng","meaning_vi":"thư giãn"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/lam-quen-ket-ban-150-cau/sentence-1d7e2355dc73f6ea11b13f08.mp3', 107),
    ('天气好，我们去打羽毛球吧。', 'Tiānqì hǎo, wǒmen qù dǎ yǔmáoqiú ba.', 'Thời tiết đẹp, chúng ta đi chơi cầu lông nhé.', '[{"chinese":"天气","pinyin":"tiānqì","meaning_vi":"thời tiết"},{"chinese":"羽毛球","pinyin":"yǔmáoqiú","meaning_vi":"cầu lông"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/lam-quen-ket-ban-150-cau/sentence-1cc19818ef20112a9eb2f119.mp3', 108),
    ('你这个周末忙吗？有时间一起玩吗？', 'Nǐ zhège zhōumò máng ma? Yǒu shíjiān yīqǐ wán ma?', 'Cuối tuần bạn có bận không? Có thời gian cùng chơi không?', '[{"chinese":"忙","pinyin":"máng","meaning_vi":"bận"},{"chinese":"时间","pinyin":"shíjiān","meaning_vi":"thời gian"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/lam-quen-ket-ban-150-cau/sentence-9a4983dc4a772545bf9bf4c2.mp3', 109),
    ('我们去市中心的咖啡厅怎么样？', 'Wǒmen qù shì zhōngxīn de kāfēitīng zěnmeyàng?', 'Chúng ta đi quán cà phê ở trung tâm thành phố thế nào?', '[{"chinese":"市中心","pinyin":"shì zhōngxīn","meaning_vi":"trung tâm thành phố"},{"chinese":"咖啡厅","pinyin":"kāfēitīng","meaning_vi":"quán cà phê"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/lam-quen-ket-ban-150-cau/sentence-e0f8a6181c0a11c78ee4bdde.mp3', 110),
    ('你下午几点方便见面？', 'Nǐ xiàwǔ jǐ diǎn fāngbiàn jiànmiàn?', 'Buổi chiều lúc mấy giờ bạn tiện gặp mặt?', '[{"chinese":"方便","pinyin":"fāngbiàn","meaning_vi":"thuận tiện, tiện"},{"chinese":"下午","pinyin":"xiàwǔ","meaning_vi":"buổi chiều"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/lam-quen-ket-ban-150-cau/sentence-5846b7be4f6813ffa9371454.mp3', 111),
    ('我们换个时间怎么样？我那天有事。', 'Wǒmen huàn gè shíjiān zěnmeyàng? Wǒ nà tiān yǒu shì.', 'Chúng ta đổi sang thời gian khác được không? Hôm đó tôi có việc.', '[{"chinese":"换个时间","pinyin":"huàn gè shíjiān","meaning_vi":"đổi sang thời gian khác"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/lam-quen-ket-ban-150-cau/sentence-d8ecd8a68b40041d8ed44dd0.mp3', 112),
    ('明天见面时间还确定吗？', 'Míngtiān jiànmiàn shíjiān hái quèdìng ma?', 'Thời gian gặp mặt ngày mai đã được xác nhận chưa?', '[{"chinese":"确定","pinyin":"quèdìng","meaning_vi":"xác nhận, chắc chắn"},{"chinese":"明天","pinyin":"míngtiān","meaning_vi":"ngày mai"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/lam-quen-ket-ban-150-cau/sentence-21aad4247b05fcc4191d8256.mp3', 113),
    ('想不想一起去尝试新餐厅？', 'Xiǎng bu xiǎng yīqǐ qù chángshì xīn cāntīng?', 'Bạn có muốn cùng đi thử nhà hàng mới không?', '[{"chinese":"尝试","pinyin":"chángshì","meaning_vi":"thử"},{"chinese":"餐厅","pinyin":"cāntīng","meaning_vi":"nhà hàng"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/lam-quen-ket-ban-150-cau/sentence-16179809020b34035ba3575e.mp3', 114),
    ('我们找个地方坐下来喝咖啡吧。', 'Wǒmen zhǎo ge dìfāng zuò xiàlai hē kāfēi ba.', 'Chúng ta tìm chỗ ngồi uống cà phê nhé.', '[{"chinese":"地方","pinyin":"dìfāng","meaning_vi":"địa điểm, chỗ"},{"chinese":"坐下来","pinyin":"zuò xiàlai","meaning_vi":"ngồi xuống"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/lam-quen-ket-ban-150-cau/sentence-5ffc7938524bc50a8efccb30.mp3', 115),
    ('今天天气很舒服，阳光不太强。', 'Jīntiān tiānqì hěn shūfu, yángguāng bù tài qiáng.', 'Hôm nay thời tiết rất dễ chịu, ánh nắng không quá gắt.', '[{"chinese":"天气","pinyin":"tiānqì","meaning_vi":"thời tiết"},{"chinese":"舒服","pinyin":"shūfu","meaning_vi":"dễ chịu"},{"chinese":"阳光","pinyin":"yángguāng","meaning_vi":"ánh nắng"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/lam-quen-ket-ban-150-cau/sentence-4951223afe560afee1c4dbcc.mp3', 116),
    ('你吃饭了吗？要不要一起去？', 'Nǐ chīfàn le ma? Yào bú yào yìqǐ qù?', 'Bạn ăn cơm chưa? Có muốn cùng đi không?', '[{"chinese":"吃饭","pinyin":"chīfàn","meaning_vi":"ăn cơm"},{"chinese":"一起","pinyin":"yìqǐ","meaning_vi":"cùng nhau"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/lam-quen-ket-ban-150-cau/sentence-b912f5d502e99b64b6994519.mp3', 117),
    ('这里交通很方便，有很多公交车。', 'Zhèlǐ jiāotōng hěn fāngbiàn, yǒu hěn duō gōngjiāo chē.', 'Giao thông ở đây rất thuận tiện, có nhiều xe buýt.', '[{"chinese":"交通","pinyin":"jiāotōng","meaning_vi":"giao thông"},{"chinese":"方便","pinyin":"fāngbiàn","meaning_vi":"thuận tiện"},{"chinese":"公交车","pinyin":"gōngjiāo chē","meaning_vi":"xe buýt"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/lam-quen-ket-ban-150-cau/sentence-78e848c554544441163d395a.mp3', 118),
    ('今天你有什么计划？我们可以一起出去走走。', 'Jīntiān nǐ yǒu shénme jìhuà? Wǒmen kěyǐ yìqǐ chūqù zǒuzou.', 'Hôm nay bạn có kế hoạch gì? Chúng ta có thể cùng ra ngoài đi dạo.', '[{"chinese":"计划","pinyin":"jìhuà","meaning_vi":"kế hoạch"},{"chinese":"出去走走","pinyin":"chūqù zǒuzou","meaning_vi":"ra ngoài đi dạo"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/lam-quen-ket-ban-150-cau/sentence-b4504582f291a1b675169a94.mp3', 119),
    ('上个周末我去爬山，风景特别美。', 'Shàng gè zhōumò wǒ qù páshān, fēngjǐng tèbié měi.', 'Cuối tuần trước tôi đi leo núi, cảnh đẹp đặc biệt.', '[{"chinese":"上个周末","pinyin":"shàng gè zhōumò","meaning_vi":"cuối tuần trước"},{"chinese":"爬山","pinyin":"páshān","meaning_vi":"leo núi"},{"chinese":"风景","pinyin":"fēngjǐng","meaning_vi":"phong cảnh"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/lam-quen-ket-ban-150-cau/sentence-bdec687bc98918ca21b0465e.mp3', 120),
    ('我觉得这座城市非常安全，也很有活力。', 'Wǒ juéde zhè zuò chéngshì fēicháng ānquán, yě hěn yǒu huólì.', 'Tôi cảm thấy thành phố này rất an toàn và rất năng động.', '[{"chinese":"城市","pinyin":"chéngshì","meaning_vi":"thành phố"},{"chinese":"安全","pinyin":"ānquán","meaning_vi":"an toàn"},{"chinese":"活力","pinyin":"huólì","meaning_vi":"năng động"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/lam-quen-ket-ban-150-cau/sentence-f91f6c876f07eda99f2150c8.mp3', 121),
    ('今天工作很忙，你觉得怎么样？', 'Jīntiān gōngzuò hěn máng, nǐ juéde zěnmeyàng?', 'Hôm nay công việc rất bận, bạn thấy thế nào?', '[{"chinese":"工作","pinyin":"gōngzuò","meaning_vi":"công việc"},{"chinese":"忙","pinyin":"máng","meaning_vi":"bận"},{"chinese":"觉得","pinyin":"juéde","meaning_vi":"cảm thấy"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/lam-quen-ket-ban-150-cau/sentence-fb5b70cacbaf6b4a0e1a074b.mp3', 122),
    ('刚才我听到一个有趣的故事，想和你分享。', 'Gāngcái wǒ tīngdào yí ge yǒuqù de gùshi, xiǎng hé nǐ fēnxiǎng.', 'Vừa rồi tôi nghe một câu chuyện thú vị và muốn chia sẻ với bạn.', '[{"chinese":"听到","pinyin":"tīngdào","meaning_vi":"nghe thấy"},{"chinese":"分享","pinyin":"fēnxiǎng","meaning_vi":"chia sẻ"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/lam-quen-ket-ban-150-cau/sentence-95899744931e62293e126fae.mp3', 123),
    ('晚上一起去喝茶，放松一下吧。', 'Wǎnshàng yīqǐ qù hē chá, fàngsōng yīxià ba.', 'Tối nay cùng đi uống trà, thư giãn một chút nhé.', '[{"chinese":"晚上","pinyin":"wǎnshàng","meaning_vi":"buổi tối"},{"chinese":"放松","pinyin":"fàngsōng","meaning_vi":"thư giãn"},{"chinese":"一起","pinyin":"yīqǐ","meaning_vi":"cùng nhau"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/lam-quen-ket-ban-150-cau/sentence-3854dbe689d2bc2173324444.mp3', 124),
    ('你喜欢这里的食物吗？我推荐一家不错的餐厅。', 'Nǐ xǐhuān zhèlǐ de shíwù ma? Wǒ tuījiàn yī jiā bùcuò de cāntīng.', 'Bạn thích thức ăn ở đây không? Tôi giới thiệu một nhà hàng khá tốt.', '[{"chinese":"食物","pinyin":"shíwù","meaning_vi":"thức ăn"},{"chinese":"推荐","pinyin":"tuījiàn","meaning_vi":"giới thiệu"},{"chinese":"餐厅","pinyin":"cāntīng","meaning_vi":"nhà hàng"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/lam-quen-ket-ban-150-cau/sentence-1a8a9bf227ec01ebccbccda3.mp3', 125),
    ('这个区域很安全，适合一个人散步。', 'Zhège qūyù hěn ānquán, shìhé yī gè rén sànbù.', 'Khu vực này rất an toàn, thích hợp để đi bộ một mình.', '[{"chinese":"区域","pinyin":"qūyù","meaning_vi":"khu vực"},{"chinese":"安全","pinyin":"ānquán","meaning_vi":"an toàn"},{"chinese":"散步","pinyin":"sànbù","meaning_vi":"đi bộ"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/lam-quen-ket-ban-150-cau/sentence-b45395199a1dbeed5ca4eeb7.mp3', 126),
    ('周末你喜欢做什么休闲活动呢？', 'Zhōumò nǐ xǐhuān zuò shénme xiūxián huódòng ne?', 'Cuối tuần bạn thích làm hoạt động giải trí gì?', '[{"chinese":"周末","pinyin":"zhōumò","meaning_vi":"cuối tuần"},{"chinese":"休闲","pinyin":"xiūxián","meaning_vi":"giải trí"},{"chinese":"活动","pinyin":"huódòng","meaning_vi":"hoạt động"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/lam-quen-ket-ban-150-cau/sentence-aaaeb1969311a00c8e39f3cc.mp3', 127),
    ('这个城市的公共交通很发达，出行很方便。', 'Zhège chéngshì de gōnggòng jiāotōng hěn fādá, chūxíng hěn fāngbiàn.', 'Giao thông công cộng của thành phố này rất phát triển, đi lại rất thuận tiện.', '[{"chinese":"公共交通","pinyin":"gōnggòng jiāotōng","meaning_vi":"giao thông công cộng"},{"chinese":"发达","pinyin":"fādá","meaning_vi":"phát triển"},{"chinese":"方便","pinyin":"fāngbiàn","meaning_vi":"thuận tiện"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/lam-quen-ket-ban-150-cau/sentence-1569131c856ef42c8b9848ff.mp3', 128),
    ('今天天气预报说明天下雨，要带伞。', 'Jīntiān tiānqì yùbào shuō míngtiān xiàyǔ, yào dài sǎn.', 'Dự báo thời tiết hôm nay nói ngày mai sẽ mưa, hãy mang theo ô.', '[{"chinese":"天气预报","pinyin":"tiānqì yùbào","meaning_vi":"dự báo thời tiết"},{"chinese":"说明","pinyin":"shuōmíng","meaning_vi":"giải thích, nói rõ"},{"chinese":"带伞","pinyin":"dài sǎn","meaning_vi":"mang ô"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/lam-quen-ket-ban-150-cau/sentence-4b3a720ac60d1bb72ed94e3a.mp3', 129),
    ('我喜欢晚上在附近公园散步，空气很好。', 'Wǒ xǐhuān wǎnshàng zài fùjìn gōngyuán sànbù, kōngqì hěn hǎo.', 'Tôi thích đi dạo ở công viên gần đây vào buổi tối, không khí rất trong lành.', '[{"chinese":"附近","pinyin":"fùjìn","meaning_vi":"gần đây"},{"chinese":"公园","pinyin":"gōngyuán","meaning_vi":"công viên"},{"chinese":"空气","pinyin":"kōngqì","meaning_vi":"không khí"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/lam-quen-ket-ban-150-cau/sentence-68d4774e8b36884524d65eb3.mp3', 130),
    ('我也觉得你的爱好很有意思。', 'Wǒ yě juéde nǐ de àihào hěn yǒuyìsi.', 'Tôi cũng thấy sở thích của bạn rất thú vị.', '[{"chinese":"爱好","pinyin":"àihào","meaning_vi":"sở thích"},{"chinese":"有意思","pinyin":"yǒuyìsi","meaning_vi":"thú vị"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/lam-quen-ket-ban-150-cau/sentence-5ca9e175713413b6f11268fb.mp3', 131),
    ('真的吗？你的经历听起来很特别！', 'Zhēn de ma? Nǐ de jīnglì tīng qǐlái hěn tèbié!', 'Thật sao? Trải nghiệm của bạn nghe rất đặc biệt!', '[{"chinese":"经历","pinyin":"jīnglì","meaning_vi":"trải nghiệm"},{"chinese":"特别","pinyin":"tèbié","meaning_vi":"đặc biệt"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/lam-quen-ket-ban-150-cau/sentence-90433946867c7244d1f9bab1.mp3', 132),
    ('你能多讲一点那个事情吗？', 'Nǐ néng duō jiǎng yīdiǎn nàgè shìqíng ma?', 'Bạn có thể nói thêm một chút về chuyện đó được không?', '[{"chinese":"事情","pinyin":"shìqíng","meaning_vi":"chuyện, sự việc"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/lam-quen-ket-ban-150-cau/sentence-ecf3ca93233b9dd9369a5cbc.mp3', 133),
    ('我也这么想，真的很有同感。', 'Wǒ yě zhème xiǎng, zhēn de hěn yǒu tónggǎn.', 'Tôi cũng nghĩ vậy, thực sự rất đồng cảm.', '[{"chinese":"同感","pinyin":"tónggǎn","meaning_vi":"sự đồng cảm"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/lam-quen-ket-ban-150-cau/sentence-43008cc14a8dff6ebf6b5e1b.mp3', 134),
    ('这个爱好听起来真不错！', 'Zhège àihào tīng qǐlái zhēn búcuò!', 'Sở thích này nghe thật hay!', '[{"chinese":"爱好","pinyin":"àihào","meaning_vi":"sở thích"},{"chinese":"不错","pinyin":"búcuò","meaning_vi":"khá hay, không tệ"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/lam-quen-ket-ban-150-cau/sentence-8bbbfb0aa629e8d8e0f1bf9e.mp3', 135),
    ('我明白你的意思了。', 'Wǒ míngbai nǐ de yìsi le.', 'Tôi hiểu ý bạn rồi.', '[{"chinese":"明白","pinyin":"míngbai","meaning_vi":"hiểu"},{"chinese":"意思","pinyin":"yìsi","meaning_vi":"ý, ý nghĩa"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/lam-quen-ket-ban-150-cau/sentence-4d80c3f943a28001ecdb732d.mp3', 136),
    ('请你再说一遍好吗？我想确认一下。', 'Qǐng nǐ zài shuō yí biàn hǎo ma? Wǒ xiǎng quèrèn yí xià.', 'Bạn vui lòng nói lại một lần được không? Tôi muốn xác nhận lại.', '[{"chinese":"确认","pinyin":"quèrèn","meaning_vi":"xác nhận"},{"chinese":"再说一遍","pinyin":"zài shuō yí biàn","meaning_vi":"nói lại một lần"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/lam-quen-ket-ban-150-cau/sentence-8de66fffa85a745702d14e91.mp3', 137),
    ('我们换个话题聊聊吧，怎么样？', 'Wǒmen huàn gè huàtí liáo liáo ba, zěnmeyàng?', 'Chúng ta đổi chủ đề nói chuyện nhé, thế nào?', '[{"chinese":"换","pinyin":"huàn","meaning_vi":"đổi"},{"chinese":"话题","pinyin":"huàtí","meaning_vi":"chủ đề"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/lam-quen-ket-ban-150-cau/sentence-fb69d5be83417f10e0d6a18d.mp3', 138),
    ('请继续讲，我很想听下去。', 'Qǐng jìxù jiǎng, wǒ hěn xiǎng tīng xiàqù.', 'Mời bạn tiếp tục kể, tôi rất muốn nghe tiếp.', '[{"chinese":"继续","pinyin":"jìxù","meaning_vi":"tiếp tục"},{"chinese":"很想","pinyin":"hěn xiǎng","meaning_vi":"rất muốn"},{"chinese":"听下去","pinyin":"tīng xiàqù","meaning_vi":"nghe tiếp"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/lam-quen-ket-ban-150-cau/sentence-e79a3469dde10dd92aa237be.mp3', 139),
    ('你的观点我完全同意。', 'Nǐ de guāndiǎn wǒ wánquán tóngyì.', 'Tôi hoàn toàn đồng ý với quan điểm của bạn.', '[{"chinese":"观点","pinyin":"guāndiǎn","meaning_vi":"quan điểm"},{"chinese":"完全","pinyin":"wánquán","meaning_vi":"hoàn toàn"},{"chinese":"同意","pinyin":"tóngyì","meaning_vi":"đồng ý"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/lam-quen-ket-ban-150-cau/sentence-28de1acf396bbb3956d93c36.mp3', 140),
    ('我得先走了，今天很开心和你聊天。', 'Wǒ děi xiān zǒu le, jīntiān hěn kāixīn hé nǐ liáotiān.', 'Tôi phải đi trước, hôm nay rất vui được trò chuyện với bạn.', '[{"chinese":"先走","pinyin":"xiān zǒu","meaning_vi":"đi trước"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/lam-quen-ket-ban-150-cau/sentence-2bc9b81b593dba3c4bbe142f.mp3', 141),
    ('谢谢你今天的分享，我学到了很多东西。', 'Xièxiè nǐ jīntiān de fēnxiǎng, wǒ xué dào le hěn duō dōngxī.', 'Cảm ơn bạn đã chia sẻ hôm nay, tôi học được rất nhiều điều.', '[{"chinese":"分享","pinyin":"fēnxiǎng","meaning_vi":"chia sẻ"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/lam-quen-ket-ban-150-cau/sentence-c4aa49bf64f32ed1e4df14ae.mp3', 142),
    ('祝你有个愉快的一天，工作顺利！', 'Zhù nǐ yǒu gè yúkuài de yì tiān, gōngzuò shùnlì!', 'Chúc bạn có một ngày vui vẻ, công việc thuận lợi!', '[{"chinese":"愉快","pinyin":"yúkuài","meaning_vi":"vui vẻ"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/lam-quen-ket-ban-150-cau/sentence-08c002899c12eca8a5826e57.mp3', 143),
    ('路上小心，回家请注意安全。', 'Lù shàng xiǎoxīn, huí jiā qǐng zhùyì ānquán.', 'Đi đường cẩn thận, về nhà chú ý an toàn nhé.', '[{"chinese":"安全","pinyin":"ānquán","meaning_vi":"an toàn"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/lam-quen-ket-ban-150-cau/sentence-e35e7edadbf973fcef3815f2.mp3', 144),
    ('我们下次再见吧，期待再聊！', 'Wǒmen xià cì zàijiàn ba, qídài zài liáo!', 'Hẹn lần sau gặp lại nhé, mong được trò chuyện tiếp!', '[{"chinese":"期待","pinyin":"qídài","meaning_vi":"mong đợi"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/lam-quen-ket-ban-150-cau/sentence-713e66a408e618a4c947f534.mp3', 145),
    ('有空我们再一起聊天，保持联系。', 'Yǒu kòng wǒmen zài yìqǐ liáotiān, bǎochí liánxì.', 'Có thời gian chúng ta nói chuyện cùng nhau nữa, giữ liên lạc nhé.', '[{"chinese":"保持","pinyin":"bǎochí","meaning_vi":"giữ"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/lam-quen-ket-ban-150-cau/sentence-b296346f2d8daef8f12be388.mp3', 146),
    ('改天我给你发消息，咱们约时间见面。', 'Gǎitiān wǒ gěi nǐ fā xiāoxi, zánmen yuē shíjiān jiànmiàn.', 'Lúc khác tôi sẽ gửi tin nhắn cho bạn, chúng ta hẹn thời gian gặp nhé.', '[{"chinese":"改天","pinyin":"gǎitiān","meaning_vi":"ngày khác, dịp khác"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/lam-quen-ket-ban-150-cau/sentence-c56aefc4a87cc5af6ecbea31.mp3', 147),
    ('谢谢你抽时间来，我们保持联系吧。', 'Xièxie nǐ chōu shíjiān lái, wǒmen bǎochí liánxì ba.', 'Cảm ơn bạn đã dành thời gian đến đây, chúng ta giữ liên lạc nhé.', '[{"chinese":"抽时间","pinyin":"chōu shíjiān","meaning_vi":"dành thời gian"},{"chinese":"保持联系","pinyin":"bǎochí liánxì","meaning_vi":"giữ liên lạc"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/lam-quen-ket-ban-150-cau/sentence-225d1fd693ebba5ca7825f22.mp3', 148),
    ('大家再见，祝你们生活愉快！', 'Dàjiā zàijiàn, zhù nǐmen shēnghuó yúkuài!', 'Tạm biệt mọi người, chúc các bạn luôn vui vẻ!', '[{"chinese":"生活愉快","pinyin":"shēnghuó yúkuài","meaning_vi":"cuộc sống vui vẻ"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/lam-quen-ket-ban-150-cau/sentence-6be0dc492579a6a555b130c4.mp3', 149),
    ('我先告辞了，下次我们继续聊！', 'Wǒ xiān gàocí le, xià cì wǒmen jìxù liáo!', 'Tôi xin phép đi trước, lần sau chúng ta tiếp tục nói chuyện nhé!', '[{"chinese":"告辞","pinyin":"gàocí","meaning_vi":"xin phép ra về"}]', 'https://ssmqppvkgffknfqdvpwg.supabase.co/storage/v1/object/public/card-audio/templates/lam-quen-ket-ban-150-cau/sentence-2e5fef91337acae9310b4197.mp3', 150)
